#include <string>
#include <vector>
#include <unordered_map>

using namespace std;

class Solution {
    unordered_map<string, string> repMap;
    unordered_map<string, string> memo;

    string resolve(const string& s) {
        string res = "";
        int i = 0, n = s.size();
        while (i < n) {
            if (s[i] == '%') {
                int j = s.find('%', i + 1);
                string key = s.substr(i + 1, j - i - 1);
                if (!memo.count(key)) {
                    memo[key] = resolve(repMap[key]);
                }
                res += memo[key];
                i = j + 1;
            } else {
                res += s[i++];
            }
        }
        return res;
    }

public:
    string applySubstitutions(vector<vector<string>>& replacements, string text) {
        for (const auto& rep : replacements) {
            repMap[rep[0]] = rep[1];
        }
        return resolve(text);
    }
};

import java.util.HashMap;
import java.util.List;
import java.util.Map;

class Solution {
    private Map<String, String> repMap = new HashMap<>();
    private Map<String, String> memo = new HashMap<>();

    private String resolve(String s) {
        StringBuilder sb = new StringBuilder();
        int i = 0, n = s.length();
        while (i < n) {
            if (s.charAt(i) == '%') {
                int j = s.indexOf('%', i + 1);
                String key = s.substring(i + 1, j);
                if (!memo.containsKey(key)) {
                    memo.put(key, resolve(repMap.get(key)));
                }
                sb.append(memo.get(key));
                i = j + 1;
            } else {
                sb.append(s.charAt(i++));
            }
        }
        return sb.toString();
    }

    public String applySubstitutions(List<List<String>> replacements, String text) {
        for (List<String> rep : replacements) {
            repMap.put(rep.get(0), rep.get(1));
        }
        return resolve(text);
    }
}

