var applySubstitutions = function(replacements, text) {
    const repMap = new Map();
    for (const [k, v] of replacements) {
        repMap.set(k, v);
    }
    const memo = new Map();

    function resolve(s) {
        let res = [];
        let i = 0, n = s.length;
        while (i < n) {
            if (s[i] === '%') {
                const j = s.indexOf('%', i + 1);
                const key = s.substring(i + 1, j);
                if (!memo.has(key)) {
                    memo.set(key, resolve(repMap.get(key)));
                }
                res.push(memo.get(key));
                i = j + 1;
            } else {
                res.push(s[i++]);
            }
        }
        return res.join('');
    }

    return resolve(text);
};
